        long k = sc.nextLong(); 

        Map<Long, Integer> prefixSumCount = new HashMap<>(); 
        prefixSumCount.put(0L, 1); 

        long prefixSum = 0; 

        long count = 0; 

        for (int i = 0; i < n; i++) { 
            prefixSum += sc.nextInt(); 

            count += prefixSumCount.getOrDefault(prefixSum - k, 0); 
            prefixSumCount.put( 
                prefixSum, 
                prefixSumCount.getOrDefault(prefixSum, 0) + 1 
            ); 
        } 

        System.out.println(count); 
        sc.close(); 
    } 
