        int n = text.length(); 
        int m = pattern.length(); 

        if (m > n) { 
            System.out.println(-1); 
            sc.close(); 
            return; 
        } 

        int[] freq = new int[26]; 


        for (int i = 0; i < m; i++) { 
            freq[pattern.charAt(i) - 'a']++; 
            freq[text.charAt(i) - 'a']--; 
        } 

        StringBuilder result = new StringBuilder(); 

        for (int i = 0; i <= n - m; i++) { 
            if (i > 0) { 
                freq[text.charAt(i - 1) - 'a']++; 
                freq[text.charAt(i + m - 1) - 'a']--; 
            } 

            boolean match = true; 

            for (int count : freq) { 
                if (count != 0) { 
                    match = false; 
                    break; 
                } 
            } 

            if (match) { 
                if (result.length() > 0) { 

                    result.append(' '); 
                } 
                result.append(i); 
            } 
        } 
        System.out.println(result.length() == 0 ? "-1" : result); 
        sc.close(); 
    } 
}

