import java.util.*; 

public class Solution { 

    public static void main(String[] args) { 
        Scanner sc = new Scanner(System.in); 

        int n = sc.nextInt(); 
        int k = sc.nextInt(); 

        int[] nums = new int[n]; 
        long left = 0; 

        long right = 0; 

        for (int i = 0; i < n; i++) { 
            nums[i] = sc.nextInt(); 
            left = Math.max(left, nums[i]); 
            right += nums[i]; 
        } 

        while (left < right) { 
            long mid = left + (right - left) / 2; 

            if (canSplit(nums, k, mid)) { 
                right = mid; 
            } else { 
                left = mid + 1; 
            } 
        } 

        System.out.println(left); 
        sc.close(); 
    } 

    private static boolean canSplit(int[] nums, int k, long maxSum) { 
        int subarrays = 1; 

        long currentSum = 0; 

        for (int num : nums) { 
            if (currentSum + num > maxSum) { 
                subarrays++; 
                currentSum = 0; 
            } 

            currentSum += num; 

            if (subarrays > k) { 
                return false; 
            } 
        } 

        return true; 
    } 
}

