        int data; 
        Node next; 


        Node(int data) { 
            this.data = data; 
            this.next = null; 
        } 
    } 

    public static void main(String[] args) { 
        Scanner sc = new Scanner(System.in); 

        int n = sc.nextInt(); 

        Node head = null; 
        Node tail = null; 

        for (int i = 0; i < n; i++) { 
            Node newNode = new Node(sc.nextInt()); 

            if (head == null) { 
                head = newNode; 
                tail = newNode; 
            } else { 
                tail.next = newNode; 
                tail = newNode; 

            } 
        } 

        int removeN = sc.nextInt(); 

        head = removeNthFromEnd(head, removeN); 

        if (head == null) { 
            System.out.println("EMPTY"); 
        } else { 
            Node current = head; 

            while (current != null) { 
                System.out.print(current.data); 

                if (current.next != null) { 
                    System.out.print(" "); 
                } 

                current = current.next; 
            } 

            System.out.println(); 
        } 


        sc.close(); 
    } 

    private static Node removeNthFromEnd(Node head, int n) { 
        Node dummy = new Node(0); 
        dummy.next = head; 

        Node fast = dummy; 
        Node slow = dummy; 

        // Move fast n nodes ahead 
        for (int i = 0; i < n; i++) { 
            fast = fast.next; 
        } 

        // Move both pointers until fast reaches the last node 
        while (fast.next != null) { 
            fast = fast.next; 
            slow = slow.next; 
        } 

        // Remove the nth node from the end 
        slow.next = slow.next.next; 


        return dummy.next; 
    } 
}

