        Node result = addTwoNumbers(l1, l2); 

        Node current = result; 
        while (current != null) { 
            System.out.print(current.digit); 

            if (current.next != null) { 
                System.out.print(" "); 
            } 

            current = current.next; 
        } 

        System.out.println(); 
        sc.close(); 
    } 

    private static Node buildList(Scanner sc, int n) { 

        Node head = null; 
        Node tail = null; 

        for (int i = 0; i < n; i++) { 
            Node newNode = new Node(sc.nextInt()); 

            if (head == null) { 
                head = newNode; 
                tail = newNode; 
            } else { 
                tail.next = newNode; 
                tail = newNode; 
            } 
        } 

        return head; 
    } 

    private static Node addTwoNumbers(Node l1, Node l2) { 
        Node dummy = new Node(0); 
        Node tail = dummy; 
        int carry = 0; 

        while (l1 != null || l2 != null || carry != 0) { 

            int sum = carry; 

            if (l1 != null) { 
                sum += l1.digit; 
                l1 = l1.next; 
            } 

            if (l2 != null) { 
                sum += l2.digit; 
                l2 = l2.next; 
            } 

            carry = sum / 10; 
            tail.next = new Node(sum % 10); 
            tail = tail.next; 
        } 

        return dummy.next; 
    } 
}

