        int count = 0; 
        Queue<Node> nodes = new LinkedList<>(); 
        Queue<Integer> maxValues = new LinkedList<>(); 

        nodes.offer(root); 
        maxValues.offer(root.val); 


        while (!nodes.isEmpty()) { 
