            int maxSoFar = maxValues.poll(); 

            if (current.val >= maxSoFar) { 
                count++; 
            } 

            int nextMax = Math.max(maxSoFar, current.val); 

            if (current.left != null) { 
                nodes.offer(current.left); 
                maxValues.offer(nextMax); 
            } 

            if (current.right != null) { 
                nodes.offer(current.right); 
                maxValues.offer(nextMax); 
            } 
        } 

        return count; 
    } 

}

