        path.add(node.val); 
        sum += node.val; 

        if (node.left == null && node.right == null && sum == target) { 
            result.add(new ArrayList<>(path)); 
        } else { 
            findPaths(node.left, target, sum, path, result); 
            findPaths(node.right, target, sum, path, result); 
        } 

        path.remove(path.size() - 1); 
    } 

