            for (char ch : word.toCharArray()) { 
                int index = ch - 'a'; 

                if (current.children[index] == null) { 
                    current.children[index] = new TrieNode(); 
                } 

                current = current.children[index]; 
            } 

            current.word = word; 
        } 

        private void dfs(char[][] board, int r, int c, TrieNode parent) { 
            char ch = board[r][c]; 

            if (ch == '#') { 
                return; 
            } 

            TrieNode node = parent.children[ch - 'a']; 


            if (node == null) { 
                return; 
            } 

            if (node.word != null) { 
                result.add(node.word); 
                node.word = null; 
            } 

            board[r][c] = '#'; 

            if (r > 0) { 
                dfs(board, r - 1, c, node); 
            } 
            if (r + 1 < board.length) { 
                dfs(board, r + 1, c, node); 
            } 
            if (c > 0) { 
                dfs(board, r, c - 1, node); 
            } 
            if (c + 1 < board[0].length) { 
                dfs(board, r, c + 1, node); 
            } 


            board[r][c] = ch; 
        } 
    } 

    public static void main(String[] args) throws IOException { 
        BufferedReader br = new BufferedReader( 
                new InputStreamReader(System.in)); 

        StringTokenizer st = new StringTokenizer(br.readLine()); 
        int rows = Integer.parseInt(st.nextToken()); 
        int cols = Integer.parseInt(st.nextToken()); 

        char[][] board = new char[rows][cols]; 

        int r = 0; 
        int c = 0; 

        while (r < rows) { 
            String line = br.readLine(); 
            if (line == null || line.trim().isEmpty()) { 
                continue; 
            } 


            st = new StringTokenizer(line); 

            while (st.hasMoreTokens() && r < rows) { 
                board[r][c] = st.nextToken().charAt(0); 
                c++; 

                if (c == cols) { 
                    c = 0; 
                    r++; 
                } 
            } 
        } 

        int numberOfWords = Integer.parseInt(br.readLine().trim()); 
        String[] words = new String[numberOfWords]; 

        for (int i = 0; i < numberOfWords; i++) { 
            words[i] = br.readLine().trim(); 
        } 

        WordSearch solver = new WordSearch(); 
        List<String> foundWords = solver.findWords(board, words); 

        for (String word : foundWords) { 

            System.out.println(word); 
        } 
    } 
}

