import java.util.*;
import java.util.regex.*;

public class Solution {
    static List<List<Integer>> result = new ArrayList<>();

    static void find(int[] arr, int start, int target, List<Integer> current) {
        if (target == 0) {
            result.add(new ArrayList<>(current));
            return;
        }

        for (int i = start; i < arr.length; i++) {
            if (arr[i] > target) {
                continue;
            }
            current.add(arr[i]);
            find(arr, i, target - arr[i], current);
            current.remove(current.size() - 1);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        StringBuilder sb = new StringBuilder();
        while (sc.hasNextLine()) {
            sb.append(sc.nextLine()).append("\n");
        }
        sc.close();
        String text = sb.toString();
        if (text.trim().isEmpty()) return;

        List<Integer> candList = new ArrayList<>();
        int target = 0;

        if (text.contains("candidates") || text.contains("target")) {
            Matcher candMatcher = Pattern.compile("candidates\\s*=\\s*\\[([^\\]]*)\\]").matcher(text);
            if (candMatcher.find()) {
                String candsStr = candMatcher.group(1).trim();
                if (!candsStr.isEmpty()) {
                    for (String s : candsStr.split(",")) {
                        candList.add(Integer.parseInt(s.trim()));
                    }
                }
            }
            Matcher targetMatcher = Pattern.compile("target\\s*=\\s*(-?\\d+)").matcher(text);
            if (targetMatcher.find()) {
                target = Integer.parseInt(targetMatcher.group(1));
            }
        } else {
            Scanner s = new Scanner(text);
            List<Integer> vals = new ArrayList<>();
            while (s.hasNextInt()) vals.add(s.nextInt());
            if (vals.isEmpty()) return;
            int n = vals.get(0);
            for (int i = 0; i < n && i + 1 < vals.size(); i++) {
                candList.add(vals.get(i + 1));
            }
            if (vals.size() > n + 1) target = vals.get(n + 1);
        }

        int[] arr = new int[candList.size()];
        for (int i = 0; i < candList.size(); i++) arr[i] = candList.get(i);
        Arrays.sort(arr);

        result.clear();
        find(arr, 0, target, new ArrayList<>());

        for (List<Integer> combination : result) {
            System.out.println(combination.toString().replace(" ", ""));
        }
    }
}

