                    fresh++; 
                } 

            } 
        } 

        if (fresh == 0) { 
            System.out.println(0); 
            sc.close(); 
            return; 
        } 

        int minutes = 0; 
        int[] dr = {-1, 1, 0, 0}; 
        int[] dc = {0, 0, -1, 1}; 

        while (!queue.isEmpty() && fresh > 0) { 
            int size = queue.size(); 
            boolean rottedThisMinute = false; 

            for (int i = 0; i < size; i++) { 
                int[] current = queue.poll(); 
                int r = current[0]; 
                int c = current[1]; 

                for (int d = 0; d < 4; d++) { 
                    int nr = r + dr[d]; 

                    int nc = c + dc[d]; 

                    if (nr < 0 || nr >= m || 
                        nc < 0 || nc >= n) { 
                        continue; 
                    } 

                    if (grid[nr][nc] == 1) { 
                        grid[nr][nc] = 2; 
                        fresh--; 
                        queue.offer(new int[]{nr, nc}); 
                        rottedThisMinute = true; 
                    } 
                } 
            } 

