public class Solution { 
    static int m, n; 
    static int[][] heights; 

    static boolean[][] bfs(boolean[][] visited, Queue<int[]> queue) { 
        int[] dr = {-1, 1, 0, 0}; 
        int[] dc = {0, 0, -1, 1}; 

        while (!queue.isEmpty()) { 
            int[] cell = queue.poll(); 
            int r = cell[0], c = cell[1]; 

            for (int d = 0; d < 4; d++) { 
                int nr = r + dr[d]; 
                int nc = c + dc[d]; 

                if (nr < 0 || nr >= m || nc < 0 || nc >= n) { 
                    continue; 
                } 


                if (!visited[nr][nc] && 
                    heights[nr][nc] >= heights[r][c]) { 
                    visited[nr][nc] = true; 
                    queue.offer(new int[]{nr, nc}); 
                } 
            } 
        } 

        return visited; 
    } 

