            for (int j = 0; j < n; j++) { 
                heights[i][j] = sc.nextInt(); 
            } 
        } 
        sc.close(); 

        boolean[][] pacific = new boolean[m][n]; 
        boolean[][] atlantic = new boolean[m][n]; 

        Queue<int[]> pq = new ArrayDeque<>(); 
        Queue<int[]> aq = new ArrayDeque<>(); 

        for (int c = 0; c < n; c++) { 
            pacific[0][c] = true; 
            pq.offer(new int[]{0, c}); 

            atlantic[m - 1][c] = true; 
            aq.offer(new int[]{m - 1, c}); 
        } 

        for (int r = 0; r < m; r++) { 
            if (!pacific[r][0]) { 
                pacific[r][0] = true; 

                pq.offer(new int[]{r, 0}); 
            } 

            if (!atlantic[r][n - 1]) { 
                atlantic[r][n - 1] = true; 
                aq.offer(new int[]{r, n - 1}); 
            } 
        } 

        bfs(pacific, pq); 
        bfs(atlantic, aq); 

        StringBuilder result = new StringBuilder("["); 
        boolean first = true; 

        for (int r = 0; r < m; r++) { 
            for (int c = 0; c < n; c++) { 
                if (pacific[r][c] && atlantic[r][c]) { 
                    if (!first) result.append(","); 
                    result.append("[") 
                          .append(r) 
                          .append(",") 
                          .append(c) 
                          .append("]"); 

                    first = false; 
                } 
            } 
        } 

        result.append("]"); 
        System.out.println(result); 
    } 
}

