        StringBuilder input = new StringBuilder(); 

        while (sc.hasNextLine()) { 
            input.append(sc.nextLine()).append(" "); 
        } 
        sc.close(); 

        Matcher matcher = Pattern.compile( 
            "\\[\\s*(-?\\d+)\\s*,\\s*(-?\\d+)\\s*\\]" 
        ).matcher(input.toString()); 

        List<int[]> points = new ArrayList<>(); 

        while (matcher.find()) { 
            int x = Integer.parseInt(matcher.group(1)); 
            int y = Integer.parseInt(matcher.group(2)); 

            points.add(new int[]{x, y}); 
        } 

        int n = points.size(); 

        if (n <= 1) { 
            System.out.println(0); 
            return; 
        } 

        int[] minCost = new int[n]; 
        boolean[] visited = new boolean[n]; 
        Arrays.fill(minCost, Integer.MAX_VALUE); 
        minCost[0] = 0; 

        long totalCost = 0; 

        for (int count = 0; count < n; count++) { 
            int u = -1; 

            for (int i = 0; i < n; i++) { 
                if (!visited[i] && 
                    (u == -1 || minCost[i] < minCost[u])) { 
                    u = i; 

                } 
            } 

            visited[u] = true; 
            totalCost += minCost[u]; 

            int[] current = points.get(u); 

            for (int v = 0; v < n; v++) { 
                if (!visited[v]) { 
                    int[] next = points.get(v); 

                    int distance = Math.abs(current[0] - next[0]) 
                                 + Math.abs(current[1] - next[1]); 

                    if (distance < minCost[v]) { 
                        minCost[v] = distance; 
                    } 
                } 
            } 
        } 

        System.out.println(totalCost); 
    } 

}

