        sc.close(); 

        Matcher matcher = Pattern.compile("\"([a-z]+)\"") 
                                 .matcher(input.toString()); 

        List<String> words = new ArrayList<>(); 

        while (matcher.find()) { 
            words.add(matcher.group(1)); 
        } 

        if (words.isEmpty()) { 
            System.out.println("\"\""); 
            return; 
        } 

        Map<Character, Set<Character>> graph = new HashMap<>(); 
        Map<Character, Integer> indegree = new HashMap<>(); 


        for (String word : words) { 
            for (char ch : word.toCharArray()) { 
                graph.putIfAbsent(ch, new HashSet<>()); 
                indegree.putIfAbsent(ch, 0); 
            } 
        } 

        for (int i = 0; i < words.size() - 1; i++) { 
            String first = words.get(i); 
            String second = words.get(i + 1); 

            int len = Math.min(first.length(), second.length()); 
            int j = 0; 

            while (j < len && first.charAt(j) == second.charAt(j)) { 
                j++; 
            } 

            if (j == len) { 
                if (first.length() > second.length()) { 
                    System.out.println("\"\""); 
                    return; 
                } 
            } else { 

                char from = first.charAt(j); 
                char to = second.charAt(j); 

                if (graph.get(from).add(to)) { 
                    indegree.put(to, indegree.get(to) + 1); 
                } 
            } 
        } 

        PriorityQueue<Character> queue = new PriorityQueue<>(); 

        for (char ch : indegree.keySet()) { 
            if (indegree.get(ch) == 0) { 
                queue.offer(ch); 
            } 
        } 

        StringBuilder order = new StringBuilder(); 

        while (!queue.isEmpty()) { 
            char current = queue.poll(); 
            order.append(current); 

            for (char next : graph.get(current)) { 

                indegree.put(next, indegree.get(next) - 1); 

                if (indegree.get(next) == 0) { 
                    queue.offer(next); 
                } 
            } 
        } 

        if (order.length() != indegree.size()) { 
            System.out.println("\"\""); 
        } else { 
            System.out.println("\"" + order + "\""); 
        } 
    } 
}

