import java.util.*; 
import java.util.regex.*; 

public class Solution { 
    public static void main(String[] args) { 
        Scanner sc = new Scanner(System.in); 
        StringBuilder input = new StringBuilder(); 


        while (sc.hasNextLine()) { 
            input.append(sc.nextLine()).append("\n"); 
        } 
        sc.close(); 

        String text = input.toString(); 

        int n = extractValue(text, "n\\s*=", 0); 
        int src = extractValue(text, "src\\s*=", -1); 
        int dst = extractValue(text, "dst\\s*=", -1); 
        int k = extractValue(text, "k\\s*=", -1); 

        List<int[]> flightsList = new ArrayList<>(); 

        Matcher matcher = Pattern.compile( 
            "\\[\\s*(-?\\d+)\\s*,\\s*(-?\\d+)\\s*,\\s*(-?\\d+)\\s*\\]" 
        ).matcher(text); 

        while (matcher.find()) { 
            flightsList.add(new int[] { 
                Integer.parseInt(matcher.group(1)), 
                Integer.parseInt(matcher.group(2)), 
                Integer.parseInt(matcher.group(3)) 
            }); 

        } 

        int[][] flights = flightsList.toArray(new int[0][]); 

        System.out.println( 
            findCheapestPrice(n, flights, src, dst, k) 
        ); 
    } 

    public static int findCheapestPrice( 
        int n, int[][] flights, int src, int dst, int k 
    ) { 
        if (n <= 0 || src < 0 || src >= n || 
            dst < 0 || dst >= n || k < 0) { 
            return -1; 
        } 

        if (src == dst) { 
            return 0; 
        } 

        int[] dist = new int[n]; 
        Arrays.fill(dist, Integer.MAX_VALUE); 
        dist[src] = 0; 


        for (int i = 0; i <= k; i++) { 
            int[] temp = Arrays.copyOf(dist, n); 

            for (int[] e : flights) { 
                int u = e[0]; 
                int v = e[1]; 
                int w = e[2]; 

                if (u >= 0 && u < n && 
                    v >= 0 && v < n && 
                    dist[u] != Integer.MAX_VALUE && 
                    dist[u] + (long) w < temp[v]) { 

                    temp[v] = dist[u] + w; 
                } 
            } 

            dist = temp; 
        } 

        return dist[dst] == Integer.MAX_VALUE ? -1 : dist[dst]; 
    } 


    private static int extractValue( 
        String text, String key, int fallback 
    ) { 
        Matcher matcher = Pattern.compile( 
            key + "\\s*(-?\\d+)" 
        ).matcher(text); 

        return matcher.find() 
            ? Integer.parseInt(matcher.group(1)) 
            : fallback; 
    } 
}

