public class Solution { 
    static int m, n; 

    static int[][] matrix, memo; 
    static int[] dr = {-1, 1, 0, 0}; 
    static int[] dc = {0, 0, -1, 1}; 

    public static void main(String[] args) { 
        Scanner sc = new Scanner(System.in); 
        List<Integer> values = new ArrayList<>(); 

        while (sc.hasNextInt()) { 
            values.add(sc.nextInt()); 
        } 
        sc.close(); 

        if (values.size() < 2) { 
            System.out.println(0); 
            return; 
        } 

        m = values.get(0); 
        n = values.get(1); 

        if (m <= 0 || n <= 0 || (long) m * n > values.size() - 2) { 
            System.out.println(0); 
            return; 

        } 

        matrix = new int[m][n]; 
        memo = new int[m][n]; 

        int index = 2; 
        for (int i = 0; i < m; i++) { 
            for (int j = 0; j < n; j++) { 
                matrix[i][j] = values.get(index++); 
            } 
        } 

        int result = 0; 

        for (int i = 0; i < m; i++) { 
            for (int j = 0; j < n; j++) { 
                result = Math.max(result, dfs(i, j)); 
            } 
        } 

        System.out.println(result); 
    } 

    static int dfs(int r, int c) { 

        if (memo[r][c] != 0) { 
            return memo[r][c]; 
        } 

        memo[r][c] = 1; 

        for (int d = 0; d < 4; d++) { 
            int nr = r + dr[d]; 
            int nc = c + dc[d]; 

            if (nr >= 0 && nr < m && 
                nc >= 0 && nc < n && 
                matrix[nr][nc] > matrix[r][c]) { 
                memo[r][c] = Math.max( 
                    memo[r][c], 
                    1 + dfs(nr, nc) 
                ); 
            } 
        } 

        return memo[r][c]; 
    } 
}

